create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,church_name text not null default 'My Church',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists contacts(id uuid primary key default gen_random_uuid(),name text,phone text not null unique,email text,sms_consent boolean not null default false,unsubscribed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists groups(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table if not exists contact_groups(contact_id uuid not null references contacts(id) on delete cascade,group_id uuid not null references groups(id) on delete cascade,created_at timestamptz not null default now(),primary key(contact_id,group_id));
create table if not exists messages(id uuid primary key default gen_random_uuid(),body text not null default '',status text not null default 'draft' check(status in ('draft','sending','sent','scheduled','completed','failed','cancelled')),created_by uuid references auth.users(id) on delete set null,scheduled_at timestamptz,total_recipients int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists message_recipients(id uuid primary key default gen_random_uuid(),message_id uuid not null references messages(id) on delete cascade,phone text not null,twilio_sid text unique,status text not null default 'queued',error_code text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists unsubscribes(phone text primary key,source text,created_at timestamptz not null default now());
create index if not exists contacts_consent_idx on contacts(sms_consent,unsubscribed);create index if not exists messages_status_idx on messages(status);create index if not exists mr_message_idx on message_recipients(message_id);create index if not exists mr_sid_idx on message_recipients(twilio_sid);
alter table profiles enable row level security;alter table contacts enable row level security;alter table groups enable row level security;alter table contact_groups enable row level security;alter table messages enable row level security;alter table message_recipients enable row level security;alter table unsubscribes enable row level security;
drop policy if exists profiles_all on profiles;create policy profiles_all on profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists contacts_all on contacts;create policy contacts_all on contacts for all to authenticated using(true) with check(true);
drop policy if exists groups_all on groups;create policy groups_all on groups for all to authenticated using(true) with check(true);
drop policy if exists contact_groups_all on contact_groups;create policy contact_groups_all on contact_groups for all to authenticated using(true) with check(true);
drop policy if exists messages_all on messages;create policy messages_all on messages for all to authenticated using(created_by=auth.uid() or created_by is null) with check(created_by=auth.uid() or created_by is null);
drop policy if exists message_recipients_all on message_recipients;create policy message_recipients_all on message_recipients for all to authenticated using(exists(select 1 from messages m where m.id=message_id and (m.created_by=auth.uid() or m.created_by is null))) with check(exists(select 1 from messages m where m.id=message_id and (m.created_by=auth.uid() or m.created_by is null)));
drop policy if exists unsubscribes_all on unsubscribes;create policy unsubscribes_all on unsubscribes for all to authenticated using(true) with check(true);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
